from pathlib import Path
root=Path(__file__).resolve().parent
brief='Put the bowl on the plate. Add extra bowls, move objects around, and place one bowl out of reach.'
base='''*{box-sizing:border-box}html{background:#fff;color:#242823}body{margin:0;width:1440px;min-height:900px;font-family:Arial,Helvetica,sans-serif;font-size:18px;line-height:1.4}h1,h2,h3,p,figure{margin:0}h1,h2,h3{font-weight:400}h1,h2,.serif{font-family:Palatino,"Palatino Linotype","Book Antiqua","URW Palladio L",serif}a{color:inherit;text-decoration:none}a:hover{text-decoration:underline;text-underline-offset:5px}button,textarea{font:inherit;color:inherit}button,a,textarea{outline-offset:5px}button{cursor:pointer}img{width:100%;height:100%;display:block;object-fit:cover;image-rendering:auto}.header{margin:0 64px;height:84px;border-bottom:1px solid #dce1da;display:flex;align-items:center;gap:64px}.wordmark{font-size:32px;letter-spacing:-1.2px}.nav{display:flex;align-items:center;gap:32px;font-size:17px}.nav a.current{color:#2c5043}.header .account{margin-left:auto;display:flex;gap:24px;align-items:center}.button{display:inline-flex;align-items:center;justify-content:center;min-height:42px;padding:10px 18px;background:#fff;border:1px solid #adb8ae;border-radius:4px;font-size:16px;line-height:1.25}.button.primary{background:#2c5043;border-color:#2c5043;color:#fff}.small{font-size:16px}.muted{color:#626b60}.pass{color:#2c5043}.fail{color:#a8342a}.numeric{font-variant-numeric:tabular-nums}.text-link{color:#2c5043;text-decoration:underline;text-underline-offset:5px}.picture{position:relative;min-height:0}.picture img{position:absolute;inset:0;object-position:50% 68%}.world-caption{display:flex;align-items:baseline;justify-content:space-between;gap:12px;padding-top:10px;font-size:17px}.world-caption span{font-size:16px}.footer{display:flex;align-items:center;justify-content:space-between;color:#626b60;font-size:16px}'''
def header(active):
 return f'''<header class="header"><a href="site-1.html" class="wordmark serif">CrashLab</a><nav class="nav" aria-label="Main navigation"><a class="{'current' if active=='worlds' else ''}" href="site-1.html#workspace">Test worlds</a><a href="page-1.html">Open bounties</a><a class="{'current' if active=='results' else ''}" href="site-2.html">Campaign results</a></nav><div class="account"><button type="button" class="button">Sign in</button></div></header>'''
def image(path,alt):return f'<img src="{path}" alt="{alt}">'
def write(name,title,css,body):
 (root/name).write_text(f'<!doctype html>\n<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} — CrashLab</title><style>{base}\n{css}</style></head><body>{body}</body></html>\n')
worlds=[('0','Extra bowls','Fail'),('2','Objects moved','Pass'),('5','Stacked objects','Pass'),('7','Bowl out of reach','Fail')]
def world_grid(cls=''):
 return ''.join(f'''<figure class="world {"selected" if i==0 else ""}"><div class="picture">{image(f'real-frames-hd/scene-task{n}.png',f'Simulator test world: {name.lower()}')}</div><figcaption class="world-caption"><p>{name}</p><span class="{outcome.lower()}">{outcome}</span></figcaption></figure>''' for i,(n,name,outcome) in enumerate(worlds))
css='''main{margin:32px 64px 0}.intro{display:flex;justify-content:space-between;align-items:end;gap:72px;margin-bottom:20px;height:106px}.intro h1{font-size:50px;line-height:1.06;letter-spacing:-1.8px}.intro p{max-width:350px;font-size:19px;line-height:1.5;padding-bottom:4px}.workspace{display:grid;grid-template-columns:416px minmax(0,1fr);gap:48px}.brief-editor{position:relative;border:1px solid #adb8ae;border-radius:6px;padding:24px}.brief-editor:after{content:"";position:absolute;left:100%;top:38px;width:48px;border-top:1px solid #adb8ae;pointer-events:none}.brief-editor label{display:block;font-size:18px;margin-bottom:16px}.brief-editor textarea{display:block;resize:none;width:100%;height:176px;border:0;padding:0;background:#fff;font-size:26px;line-height:1.4;letter-spacing:-.5px}.editor-actions{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-top:20px}.editor-actions span{font-size:16px;color:#626b60}.explanation{padding-top:24px}.explanation h2{font-size:28px;letter-spacing:-.5px;line-height:1.15;margin-bottom:10px}.explanation p{font-size:17px;color:#626b60;line-height:1.5;max-width:370px}.output-head{display:flex;justify-content:space-between;align-items:baseline;margin-bottom:14px;height:26px}.output-head h2{font-family:Arial,Helvetica,sans-serif;font-size:18px}.worlds{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px 20px}.world{display:grid;grid-template-columns:220px minmax(0,1fr);gap:16px;min-height:220px}.world .picture{height:220px}.world .picture img{object-position:center}.world-caption{padding:0;display:flex;flex-direction:column;align-items:flex-start;justify-content:center;gap:14px}.world-caption p{font-family:Palatino,"Palatino Linotype","Book Antiqua","URW Palladio L",serif;font-size:24px;line-height:1.12}.world-caption span{font-size:17px}.world.selected .world-caption:after{content:"Wrong object";font-size:16px;color:#626b60}.bounty-strip{display:flex;justify-content:space-between;align-items:center;border-top:1px solid #adb8ae;border-bottom:1px solid #dce1da;padding:18px 0;margin-top:24px;height:76px;gap:32px}.bounty-strip h2{font-size:25px;line-height:1.1}.bounty-strip p{margin-top:5px;font-size:16px;color:#626b60}.bounty-strip .offer{font-size:20px}.bounty-strip .button{margin-left:14px}.footer{margin-top:16px}'''
body=header('worlds')+f'''<main><section class="intro"><h1>Write the test in words.<br>See the worlds it builds.</h1><p>Crash tests made cars safe.<br>Test robot AI before it meets the world.</p></section><section class="workspace" id="workspace"><div><div class="brief-editor"><label for="world-brief">Your test brief</label><textarea id="world-brief" spellcheck="false" aria-describedby="example-note">{brief}</textarea><div class="editor-actions"><button class="button primary" type="button">Build test worlds</button><span id="example-note">Example brief</span></div></div><div class="explanation"><h2>Your brief, made tangible.</h2><p>Same task. Different objects and positions.<br>The failures show you what to fix.</p></div></div><section aria-labelledby="worlds-title"><div class="output-head"><h2 id="worlds-title">From this brief: four test worlds</h2><a class="text-link small" href="site-2.html">View campaign result</a></div><div class="worlds">{world_grid()}</div></section></section><section class="bounty-strip"><div><h2>Put your next fix to the test.</h2><p>Open challenges, recorded evidence and rewards for passing results.</p></div><div><span class="offer serif numeric">5,000 USDC / Bowl placement</span><a class="button" href="page-1.html">Explore open bounties</a></div></section><footer class="footer"><span>Shown with SmolVLA. Outcomes are illustrative.</span><span>Sample data</span></footer></main>'''
write('site-1.html','Describe a test world',css,body)
css='''main{margin:20px 64px 0}.brief-top{display:grid;grid-template-columns:1fr 320px;gap:64px;padding-bottom:18px;border-bottom:1px solid #dce1da}.campaign-label{font-size:16px;color:#626b60;margin-bottom:10px}.brief-top h1{font-family:Arial,Helvetica,sans-serif;font-size:26px;line-height:1.35;max-width:870px;font-weight:400;letter-spacing:-.3px}.campaign-summary{border-left:1px solid #dce1da;padding-left:28px}.campaign-summary .model{font-size:17px;margin-bottom:10px}.campaign-summary .score{font-size:45px;line-height:1.1}.campaign-summary .score span{font-size:22px}.campaign-summary .summary-note{font-size:16px;color:#626b60;margin-top:8px}.campaign-body{display:grid;grid-template-columns:410px minmax(0,1fr);gap:38px;margin-top:24px}.section-head{display:flex;align-items:baseline;justify-content:space-between;margin-bottom:15px}.section-head h2{font-size:28px;line-height:1.1}.worlds{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px 16px}.world .picture{height:132px}.world-caption{padding-top:8px;align-items:start;gap:6px;min-height:48px;font-size:16px}.world-caption p{max-width:130px}.world-caption span{font-size:16px}.selected .picture{outline:2px solid #a8342a;outline-offset:3px}.world-note{border-top:1px solid #dce1da;margin-top:16px;padding-top:14px;font-size:16px;color:#626b60;line-height:1.5}.world-note .fail{display:block;margin-bottom:6px;font-size:18px}.opened{min-width:0}.replay-layout{display:grid;grid-template-columns:382px minmax(0,1fr);gap:26px}.run-frame{height:262px}.run-frame img{object-position:35% 77%}.run-frame:after{content:"";position:absolute;left:42px;top:155px;width:105px;height:63px;border:2px solid #a8342a}.replay-controls{display:flex;justify-content:space-between;align-items:center;margin-top:12px;font-size:16px}.replay-controls button{border:0;border-bottom:1px solid #2c5043;background:#fff;color:#2c5043;padding:0 0 3px;font-size:16px}.incident h3{font-family:Palatino,"Palatino Linotype","Book Antiqua","URW Palladio L",serif;font-size:30px;line-height:1.12;margin-bottom:12px}.incident p{font-size:18px;line-height:1.45}.incident .meta{font-size:16px;color:#626b60;margin-top:18px}.incident .finding{font-size:16px;border-top:1px solid #dce1da;margin-top:18px;padding-top:12px}.comparison{margin-top:16px;border-top:1px solid #adb8ae;padding-top:16px}.comparison-head{display:flex;justify-content:space-between;align-items:baseline;margin-bottom:12px}.comparison-head h2{font-size:25px}.comparison-head span{font-size:16px;color:#626b60}.compare-grid{display:grid;grid-template-columns:1fr 1fr;gap:24px}.compare-item{display:grid;grid-template-columns:112px 1fr;gap:14px;align-items:center}.compare-item .picture{height:112px}.compare-item .picture img{object-position:30% 68%}.compare-item h3{font-size:16px;margin-bottom:5px}.compare-item .metric{font-size:36px;line-height:1.15}.compare-item .metric span{font-size:18px}.compare-item .result{font-size:16px;margin-top:5px}.footer{border-top:1px solid #dce1da;margin-top:16px;padding-top:16px;gap:24px}.footer-links{display:flex;gap:22px}.footer .sample{margin-left:auto}.sub-note{font-size:16px;color:#626b60;margin-top:13px}'''
body=header('results')+f'''<main><section class="brief-top"><div><p class="campaign-label">Campaign result / Your brief, as written</p><h1>“{brief}”</h1></div><aside class="campaign-summary"><p class="model">SmolVLA / Before the fix</p><p class="score serif numeric">71 <span>± 4 / 100</span></p><p class="summary-note">213 of 300 scenes passed</p></aside></section><section class="campaign-body"><section><div class="section-head"><h2>Worlds from your brief</h2><span class="small muted">4 shown</span></div><div class="worlds">{world_grid()}</div><p class="world-note"><span class="fail">Opened: extra bowls</span>World setup images shown above.<br>Two of these four sample runs failed.</p></section><section class="opened" id="opened-failure"><div class="section-head"><h2>One failure, up close</h2><span class="small muted">Original run</span></div><div class="replay-layout"><div><figure class="picture run-frame">{image('real-frames/task0-2.png','Recorded simulator frame: gripper lifts the plate while bowls remain on the table')}</figure><div class="replay-controls"><button type="button">Replay the recorded run</button><span class="numeric muted">2.84 / 8.00 s</span></div></div><aside class="incident"><h3 class="fail">The plate moved.<br>The bowl did not.</h3><p>With extra bowls nearby, the gripper selected the plate instead of the target bowl.</p><p class="meta">Found by variation bot<br>Failure type: wrong object</p><p class="finding">Fix tried: verify the target object before closing the gripper.</p></aside></div><section class="comparison"><div class="comparison-head"><h2>After the fix: 22 points higher</h2><span>Illustrative rerun / 300 scenes</span></div><div class="compare-grid"><article class="compare-item"><figure class="picture">{image('real-frames/task0-2.png','Before-fix sample frame showing the lifted plate')}</figure><div><h3>Before / Original model</h3><p class="metric serif numeric">71 <span>± 4 / 100</span></p><p class="result fail">Wrong object lifted</p></div></article><article class="compare-item"><figure class="picture">{image('real-frames/task3-3.png','Illustrative after-fix frame with a bowl resting on the plate')}</figure><div><h3>After / Target check</h3><p class="metric serif numeric">93 <span>± 2 / 100</span></p><p class="result pass">Bowl placed on plate</p></div></article></div><p class="sub-note">Illustrative comparison. Scores and ranges are sample data.</p></section></section></section><footer class="footer"><div class="footer-links"><a class="text-link" href="page-2.html">View 5,000 USDC bounty</a><a class="text-link" href="page-2.html">Open leaderboard</a></div><span class="sample">Sample data</span></footer></main>'''
write('site-2.html','Campaign result',css,body)
